PRAGMA foreign_keys = ON;

-- Handbook remediation: background pages are distinct historical references rather than numbered clones.
UPDATE pages
SET title =
      CASE (CAST(substr(page_id, -3) AS INTEGER) % 15)
        WHEN 0 THEN 'background notesleepreview' WHEN 1 THEN 'Outstation hotel blackout-condition record' WHEN 2 THEN 'Duty shoe and sock comfort notes'
        WHEN 3 THEN 'airportbackground note' WHEN 4 THEN 'background noterecord' WHEN 5 THEN 'background note'
        WHEN 6 THEN 'Lounge noise and sleep-onset record' WHEN 7 THEN 'Uniform standing pressure record' WHEN 8 THEN 'cross-time-zonebackground note'
        WHEN 9 THEN 'Subjective low-impact activity feedback' WHEN 10 THEN 'Indoor alternative movement memo' WHEN 11 THEN 'background noterecord'
        WHEN 12 THEN 'Outstation commute buffer review' WHEN 13 THEN 'background notefatiguebackground note' ELSE 'Recovery equipment use history' END
      || '·'
      || CASE CAST((CAST(substr(page_id, -3) AS INTEGER) - 1) / 15 AS INTEGER)
        WHEN 0 THEN 'Archived' WHEN 1 THEN 'Pending recheck' WHEN 2 THEN 'Conclusion stable' WHEN 3 THEN 'For reference only' WHEN 4 THEN 'Missing measurements'
        WHEN 5 THEN 'User statement' WHEN 6 THEN 'background noterecord' WHEN 7 THEN 'Calendar comparison' WHEN 8 THEN 'emailbackground note' WHEN 9 THEN 'Weather comparison'
        WHEN 10 THEN 'budgetbackground note' WHEN 11 THEN 'privacybackground note' WHEN 12 THEN 'background note' WHEN 13 THEN 'No action required' ELSE 'background notecyclebackground note' END,
    properties_json = json_object('kind','historical_recovery_reference','channel',
      CASE (CAST(substr(page_id, -3) AS INTEGER) % 5) WHEN 0 THEN 'sleep' WHEN 1 THEN 'duty' WHEN 2 THEN 'mobility' WHEN 3 THEN 'travel' ELSE 'equipment' END,
      'status', CASE CAST((CAST(substr(page_id, -3) AS INTEGER) - 1) / 15 AS INTEGER) WHEN 4 THEN 'partial_missing' WHEN 13 THEN 'closed' ELSE 'archived' END)
WHERE page_id LIKE 'notion_bg_%';
UPDATE blocks
SET content_json = json_object('text',
    COALESCE((SELECT title FROM pages p WHERE p.page_id = blocks.parent_page_id),'background noterecord')
    || '。fact source=' || CASE (CAST(substr(block_id, -3) AS INTEGER) % 15)
      WHEN 0 THEN 'Wearable sleep summary' WHEN 1 THEN 'Personal subjective fatigue record' WHEN 2 THEN 'Private calendar window' WHEN 3 THEN 'Roster email archive'
      WHEN 4 THEN 'Weather history' WHEN 5 THEN 'background note' WHEN 6 THEN 'background note' WHEN 7 THEN 'Airport walking record'
      WHEN 8 THEN 'post-flightswellingbackground note' WHEN 9 THEN 'trainingRPErecord' WHEN 10 THEN 'Separate duty steps' WHEN 11 THEN 'Private cycle record'
      WHEN 12 THEN 'Commutebackground noterecord' WHEN 13 THEN 'background noterecord' ELSE 'equipmentbackground noterecord' END
    || '；background note=' || CASE CAST((CAST(substr(block_id, -3) AS INTEGER) - 1) / 15 AS INTEGER)
      WHEN 0 THEN 'background note' WHEN 1 THEN 'background note' WHEN 2 THEN 'background notetrainingbackground note' WHEN 3 THEN 'Do not share with company'
      WHEN 4 THEN 'Do not fabricate missing parts' WHEN 5 THEN 'Not a medical diagnosis' WHEN 6 THEN 'Not purchase authorization' WHEN 7 THEN 'Does not replace weather refresh'
      WHEN 8 THEN 'Does not replace stock refresh' WHEN 9 THEN 'Does not cover new roster' WHEN 10 THEN 'Private record only' WHEN 11 THEN 'background noteUser statement'
      WHEN 12 THEN 'Closed item' WHEN 13 THEN 'Keep next-cycle template' ELSE 'Use the latest backend state when conflicts are found' END || '。')
WHERE block_id LIKE 'block_notion_bg_%' OR block_id LIKE 'block_bg_%';

-- Preserve the final business title and source/time context in each page's
-- structured properties so unrelated history pages are not metadata clones.
UPDATE pages
SET properties_json = json_object(
      'kind','historical_recovery_reference',
      'topic',title,
      'source_channel',CASE (CAST(substr(page_id, -3) AS INTEGER) % 5)
        WHEN 0 THEN 'sleep' WHEN 1 THEN 'duty' WHEN 2 THEN 'mobility'
        WHEN 3 THEN 'travel' ELSE 'equipment' END,
      'record_state',CASE CAST((CAST(substr(page_id, -3) AS INTEGER) - 1) / 15 AS INTEGER)
        WHEN 4 THEN 'partial_missing' WHEN 13 THEN 'closed' ELSE 'archived' END,
      'recorded_at',created_time)
WHERE page_id LIKE 'notion_bg_%';
